 public function __construct(private SurveyJobService$s){}public function index(Request$r):Response{return$this->read($r,fn($x)=>$this->s->list($x[0],$x[1],$this->id($r,'projectId','survey_project_not_found')));}public function show(Request$r):Response{return$this->read($r,fn($x)=>$this->s->get($x[0],$x[1],$this->id($r,'jobId','survey_job_not_found')));}public function create(Request$r):Response{return$this->write($r,function($b,$x)use($r){$b['projectId']=$this->id($r,'projectId','survey_project_not_found');return Response::success($this->s->create($x[0],$x[1],$x[2],$b),status:201);});}public function observation(Request$r):Response{return$this->write($r,fn($b,$x)=>Response::success($this->s->addObservation($x[0],$x[1],$x[2],$this->id($r,'jobId','survey_job_not_found'),$this->version($b),$b),status:201));}public function deliverable(Request$r):Response{return$this->write($r,fn($b,$x)=>Response::success($this->s->addDeliverable($x[0],$x[1],$x[2],$this->id($r,'jobId','survey_job_not_found'),$this->version($b),$b),status:201));}public function fees(Request$r):Response{return$this->write($r,fn($b,$x)=>Response::success($this->s->estimateFees($x[0],$x[1],$x[2],$this->id($r,'jobId','survey_job_not_found'),$this->version($b),$b)));}public function issue(Request$r):Response{return$this->write($r,fn($b,$x)=>Response::success($this->s->issue($x[0],$x[1],$x[2],$this->id($r,'jobId','survey_job_not_found'),$this->version($b),($b['humanConfirmed']??false)===true,is_string($b['professionalRole']??null)?$b['professionalRole']:'',is_string($b['reason']??null)?$b['reason']:'',is_string($b['externalReference']??null)?$b['externalReference']:'')));}public function export(Request$r):Response{try{$x=$this->scope($r);if($x instanceof Response)return$x;$format=$r->attribute('format');if(!is_string($format))throw new SurveyJobException('survey_export_format_invalid');$f=$this->s->export($x[0],$x[1],$this->id($r,'jobId','survey_job_not_found'),$format);return Response::binary($f['content'],$